&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;ldquo;BU SİSTEM &amp;Ccedil;&amp;Uuml;R&amp;Uuml;M&amp;Uuml;ŞT&amp;Uuml;R&lt;/span&gt;&lt;/strong&gt;&lt;strong&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;rdquo;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;ldquo;İ&amp;ccedil;erisinde yaşadığımız bu d&amp;uuml;zen, bozuk bir d&amp;uuml;zendir! Ve bozuk tezgahtan sağlam &amp;uuml;r&amp;uuml;n &amp;ccedil;ıkmaz! Bizim m&amp;uuml;cadelemiz: bu bozuk sistemi değiştirme m&amp;uuml;cadelesidir! &amp;Ccedil;ok net s&amp;ouml;yl&amp;uuml;yorum: biz iktidarın alternatifi değiliz! Biz bu bozuk sistemin alternatifiyiz! Ve Allah&amp;rsquo;ın izniyle bu sistemi biz değiştireceğiz!&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
